		&\approx_\delta \Big( \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{O}^{x,z,r,s} \Big)_{\alice \alice'} \\
		&\approx_\delta \Big( \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{O}^{x,z,r,s} \Big)_{\bob \alice''} \\
		&\approx_\delta \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\bob \alice''}\,.
	\end{align*}
